// Training corpus generator.
//
// Every example carries the id of the template that produced it. The trainer
// splits on THAT id, never on the row, so the held-out set contains phrasings
// the model has genuinely never seen. Splitting by row would let near-identical
// siblings sit on both sides and would report a score that means nothing.

const pick = (a, r) => a[Math.floor(r() * a.length)];
function rng(seed) { let s = seed >>> 0; return () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296; }

const BRAND = ['Amazon','Apple','Netflix','PayPal','Costco','Walmart','Chase','Wells Fargo','Bank of America','HSBC','Barclays','Halifax','Lloyds','USPS','FedEx','UPS','DHL','Royal Mail','Evri','Spotify','Hulu','Disney+','Microsoft','Google'];
