export function build(perTemplate = 26, seed = 7) {
  const r = rng(seed);
  const rows = [];
  for (const [id, fn] of SCAM) for (let i = 0; i < perTemplate; i++) rows.push({ text: fn(r), label: 1, tpl: 'S:' + id });
  for (const [id, fn] of LEGIT) for (let i = 0; i < perTemplate; i++) rows.push({ text: fn(r), label: 0, tpl: 'L:' + id });
  return rows;
}
export const TEMPLATE_COUNT = { scam: SCAM.length, legit: LEGIT.length };
